#!/usr/bin/env node

import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { BOX_ENV, BOX_WORD } from './box-words.mjs';

export const SRC = '.vscode/tasks.json';
export const OUT = 'specifications/onboarding/TASKS.md';

export function boxesOf(task) {
  const o = (task && task.options) || {};
  const shell = o.shell || {};
  const texts = [task && task.command, ...((task && task.args) || []).map(a => (a && typeof a === 'object' ? a.value : a)),
    o.cwd, ...Object.values(o.env || {}), shell.executable, ...(shell.args || [])];
  return [...new Set(texts.filter(s => typeof s === 'string').flatMap(s => [...s.matchAll(/\$\{input:(\w+)\}/g)].map(m => m[1])))];
}

export function readInputs(file = SRC) {
  const d = JSON.parse(readFileSync(file, 'utf8').replace(/^\s*\/\/.*$/gm, ''));
  return new Map((d.inputs || []).map(i => [i.id, i]));
}

export function readTasks(file = SRC) {
  const raw = readFileSync(file, 'utf8').replace(/^\s*\/\/.*$/gm, '');
  const d = JSON.parse(raw);
  const inputs = new Map((d.inputs || []).map(i => [i.id, i]));
  return (d.tasks || []).filter(t => t && t.label).map(t => ({
    label: t.label,
    detail: String(t.detail || '').trim(),
    boxes: boxesOf(t)
      .map(id => ({ id, description: String((inputs.get(id) || {}).description || '').trim(),
                    options: (inputs.get(id) || {}).options || null })),
  }));
}

export function entryLines(t, values = null) {
  const L = [];
  L.push(`## \`${t.label}\``);
  L.push('');
  L.push(t.detail || '*This task carries no description of its own, which is the one thing every task here owes a reader.*');
  L.push('');
  if (!t.boxes.length) {
    L.push('**Opens no box.** It takes what the build already knows.');
  } else {
    L.push(`**Opens ${t.boxes.length} box${t.boxes.length === 1 ? '' : 'es'}, in this order:**`);
    L.push('');
    t.boxes.forEach((b, i) => {
      const opts = b.options ? ` *(${b.options.join(' · ')})*` : '';
      const line = `${i + 1}. ${b.description || `\`${b.id}\``}${opts}`;
      if (!values) { L.push(line); return; }
      const v = String(values[b.id] ?? '');
      const pad = ' '.repeat(`${i + 1}. `.length);
      L.push(v.trim() ? `${line} — "${v.replace(/\r\n?/g, '\n').split('\n').join(`\n${pad}`)}"` : `${line} — left empty`);
    });
  }
  L.push('');
  return L;
}

export const TASK_ENV = 'SPOCK_TASK';
export const RAN_HEADING = '## The task that ran';
export const RAN_NOT_NAMED = 'Not named: this was started outside VS Code\'s task list, so which task it was, and which boxes it opened, is not known here.';
export const ranNotATask = label => `\`${label}\` is not a task in .vscode/tasks.json as it stands, so its boxes are not listed here.`;

export function ranSection(label, env = process.env, tasks = null) {
  const L = [RAN_HEADING, ''];
  const name = label === undefined || label === null ? '' : String(label);
  if (!name.trim()) return [...L, RAN_NOT_NAMED].join('\n');
  let all = tasks;
  if (!all) { try { all = readTasks(); } catch { all = []; } }
  const t = all.find(x => x.label === name);
  if (!t) return [...L, ranNotATask(name)].join('\n');
  const values = Object.fromEntries(t.boxes.map(b => [b.id, env[BOX_ENV + b.id] ?? '']));
  const [first, ...rest] = entryLines(t, values);
  return [...L, first.replace(/^## /, ''), ...rest].join('\n').replace(/\n+$/, '');
}

export function render(tasks = readTasks()) {
  const L = [];
  L.push('# The tasks, and what each one does');
  L.push('');
  L.push('> **Generated from `.vscode/tasks.json` by `.github/scripts/task-page.mjs`. Do not edit this file.**');
  L.push('> Change a task and regenerate: `node .github/scripts/task-page.mjs --write`. **C179** compares the');
  L.push('> two and fails the build when they disagree.');
  L.push('');
  L.push('**A task is how a person does the half of the process an agent cannot.** On the Copilot surface the');
  L.push('agent holds no terminal, so anything that writes to the run record, signs a gate or runs a check');
  L.push('happens here. An agent may start a task that carries no box; a task that opens one ends the agent\'s');
  L.push('turn, and that is the mechanism a signature rests on.');
  L.push('');
  L.push(`**${tasks.length} tasks.** Every one is in the command palette under its full label, once you choose \`Tasks: Run Task\` there: the palette does not list task labels on its own.`);
  L.push('');
  L.push('---');
  L.push('');
  for (const t of tasks) L.push(...entryLines(t));
  return L.join('\n').replace(/\n+$/, '') + '\n';
}

if (process.argv[1] && resolve(fileURLToPath(import.meta.url)) === resolve(process.argv[1])) {
  const out = render();
  if (process.argv.includes('--write')) { writeFileSync(OUT, out); console.log(`wrote ${OUT}`); }
  else process.stdout.write(out);
}
